    // Internal function to calculate the fib4 number
    // This is a helper to represent the fib4 logic
    var fib4_internal := (n: int) => {
        if n == 0 then 0
        else if n == 1 then 0
        else if n == 2 then 2
        else if n == 3 then 0
        else fib4_internal(n - 1) + fib4_internal(n - 2) + fib4_internal(n - 3) + fib4_internal(n - 4)
    };

    // Initialize an array to store the computed values
    var fib4_values := new int[n + 1];
    fib4_values[0] := 0;
    fib4_values[1] := 0;
    fib4_values[2] := 2;
    fib4_values[3] := 0;

    // Fill the array iteratively
    var i := 4;
    while i <= n
        invariant 4 <= i <= n + 1
        invariant fib4_values[0] == 0 && fib4_values[1] == 0 && fib4_values[2] == 2 && fib4_values[3] == 0
        invariant forall j :: 0 <= j < i ==> fib4_values[j] == fib4_internal(j)
    {
        fib4_values[i] := fib4_values[i - 1] + fib4_values[i - 2] + fib4_values[i - 3] + fib4_values[i - 4];
        i := i + 1;
    }

    result := fib4_values[n];
}

